        if (isRef(res)) {
            const value = targetIsArray && isIntegerKey(key) ? res : res.value
            return isReadonly && isObject(value) ? readonly(value) : value
        }

        if (isObject(res)) {
            return isReadonly ? readonly(res) : reactive(res)
        }

        return res
    }
